formal_description.statement:
Let (L, E) be an execution-exceedance requirement. Define:
I(L) := {i in {1, ..., n} | (L + T_i - D_i) mod T_i > T_i - D_i}
I_star(L, Theta) := {i in I(L) | (L + T_i - D_i) mod T_i >= (T_i - Theta_i)}

1. If sum_i_equals_1_to_n(ceil((L + T_i - D_i) / T_i)) * C_i + sum_i_in_I(L)(C_i) <= E, then T_star_theta(L, E) = False.
2. If sum_i_equals_1_to_n(ceil((L + T_i - D_i) / T_i)) * C_i + sum_i_in_I_star(L, Theta)(C_i) > E, then T_star_theta(L, E) = True.

informal_sketch.pseudocode:
def calculate_num_jobs_in_interval(L, T_i, D_i):
    # Number of jobs of tau_i with release >= a and deadline <= b
    # This is ceil((L + T_i - D_i) / T_i) for constrained deadlines
    return math.ceil((L + T_i - D_i) / T_i)

def calculate_I_L(L, task_set):
    I_L = set()
    for i, task_i in enumerate(task_set):
        # Check if a carry-in job is possible for task_i
        # (L + T_i - D_i) mod T_i > T_i - D_i
        if (L + task_i.T - task_i.D) % task_i.T > (task_i.T - task_i.D):
            I_L.add(i)
    return I_L

def calculate_I_star_L_Theta(L, I_L, task_set, Theta):
    I_star_L_Theta = set()
    for i in I_L:
        task_i = task_set[i]
        # Check if carry-in job can be executed non-work-conservingly
        # (L + T_i - D_i) mod T_i >= T_i - Theta_i
        if (L + task_i.T - task_i.D) % task_i.T >= (task_i.T - Theta[i]):
            I_star_L_Theta.add(i)
    return I_star_L_Theta

def test_requirement_lemma_6(L, E, task_set, Theta):
    I_L = calculate_I_L(L, task_set)
    I_star_L_Theta = calculate_I_star_L_Theta(L, I_L, task_set, Theta)

    # Condition 1: Check if T_star_theta(L, E) = False
    total_demand_upper_bound = 0
    for i, task_i in enumerate(task_set):
        total_demand_upper_bound += calculate_num_jobs_in_interval(L, task_i.T, task_i.D) * task_i.C
    for i in I_L:
        total_demand_upper_bound += task_set[i].C # Add potential carry-in

    if total_demand_upper_bound <= E:
        return False # Requirement does not hold

    # Condition 2: Check if T_star_theta(L, E) = True
    total_demand_lower_bound = 0
    for i, task_i in enumerate(task_set):
        total_demand_lower_bound += calculate_num_jobs_in_interval(L, task_i.T, task_i.D) * task_i.C
    for i in I_star_L_Theta:
        total_demand_lower_bound += task_set[i].C # Add guaranteed carry-in

    if total_demand_lower_bound > E:
        return True # Requirement holds

    return None # Cannot determine (neither condition met)

def is_dominated(req1, req2):
    # req1 is dominated by req2 if req1's condition implies req2's condition
    # and req2 is 'easier' to satisfy.
    return req2.E <= req1.E and req2.L >= req1.L

def remove_dominated_requirements(R_set):
    to_remove = set()
    for req1 in R_set:
        for req2 in R_set:
            if req1 != req2 and is_dominated(req1, req2):
                to_remove.add(req1)
                break # req1 is dominated by req2, no need to check other req2
    R_set.difference_update(to_remove)
    return R_set
